import os


DEFAULT_BACKEND_API = "https://gpt.autohome.com.cn"
AHDEV_DIR = os.path.expanduser("~/.ahdev")
CONFIG_FILE = os.path.join(AHDEV_DIR, "config.json")


def _load_config() -> dict:
    try:
        import json
        if os.path.exists(CONFIG_FILE):
            with open(CONFIG_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return {}


def get_backend_api() -> str:
    """统一获取后端地址，关键路径保持与 secure_api 一致。"""
    config = _load_config()
    if config.get("backend_api"):
        return config["backend_api"]
    env_val = os.environ.get("AHCLAUDE_BACKEND_API")
    if env_val:
        return env_val
    return DEFAULT_BACKEND_API


BACKEND_API = get_backend_api()
